using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
using UsbRecovery;

public static class RaidControllerRecoveryTests
{
    public sealed class Fixture { public string name,format,sha256,kind; public int level,disks,role; public long bytes; }
    public sealed class ArrayOracle { public int level; public long logical_bytes; public string logical_sha256,layout; }
    public sealed class Manifest { public List<Fixture> cases; public List<ArrayOracle> arrays; }
    static string fixtures,work; static Manifest manifest; static int checks,number;
    static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
    static string Hash(string path){using(var input=File.OpenRead(path))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant();}
    static string PathOf(Fixture f){return Path.Combine(fixtures,f.name.Substring(0,f.name.Length-3));}
    static uint Be32(byte[] b,int at){return (uint)b[at]<<24|(uint)b[at+1]<<16|(uint)b[at+2]<<8|b[at+3];}
    static ulong Be64(byte[] b,int at){return ((ulong)Be32(b,at)<<32)|Be32(b,at+4);}
    static void Put32(byte[] b,int at,uint value){for(int i=3;i>=0;i--){b[at+i]=(byte)value;value>>=8;}}
    static void Put64(byte[] b,int at,ulong value){Put32(b,at,(uint)(value>>32));Put32(b,at+4,(uint)value);}
    static void Le32(byte[] b,int at,uint value){Buffer.BlockCopy(BitConverter.GetBytes(value),0,b,at,4);}
    static void DdfCrc(byte[] b,int at,int bytes){uint crc=0;for(int i=0;i<bytes;i++){crc^=i>=4&&i<8?(byte)255:b[at+i];for(int bit=0;bit<8;bit++)crc=(crc>>1)^(0xedb88320U*(crc&1));}Put32(b,at+4,crc);}
    static RaidMetadataProbe.Report Probe(params string[] paths){var hashes=paths.ToDictionary(p=>p,Hash);var r=RaidMetadataProbe.Probe(paths,CancellationToken.None);foreach(var p in hashes)Check(Hash(p.Key)==p.Value,"source image bytes unchanged");Check(r.MetadataBytesRead<=RaidMetadataProbe.MaximumControllerMetadataBytes*(long)paths.Length,"bounded controller metadata read and reread");return r;}
    static void NoConfiguration(RaidMetadataProbe.Report r,string why){Check(r.Groups.All(g=>g.Configuration==null&&g.Status!="candidate"),why);}
    static bool Has(RaidMetadataProbe.Report r,string code){return r.Members.Any(m=>m.Code==code||m.Reasons.Contains(code))||r.Groups.Any(g=>g.Reasons.Contains(code));}
    static string Mutate(Fixture f,Action<byte[]> mutation){byte[] b=File.ReadAllBytes(PathOf(f));mutation(b);string path=Path.Combine(work,(++number)+"-mutated.dd");File.WriteAllBytes(path,b);return path;}
    static void Section(byte[] b,int field,Action<byte[],int,int> change){int anchor=b.Length-512;foreach(int p in new[]{96,104}){ulong lba=Be64(b,anchor+p);if(lba==UInt64.MaxValue)continue;int h=checked((int)lba*512);int at=checked(h+(int)Be32(b,h+field)*512),bytes=checked((int)Be32(b,h+field+4)*512);change(b,at,bytes);}}
    static void Header(byte[] b,Action<byte[],int> change){int a=b.Length-512;foreach(int p in new[]{96,104}){ulong lba=Be64(b,a+p);if(lba==UInt64.MaxValue)continue;int at=checked((int)lba*512);change(b,at);DdfCrc(b,at,512);}}
    static void Reject(Fixture f,string code,Action<byte[]> change){var r=Probe(Mutate(f,change));NoConfiguration(r,"invalid mapping produces no configuration: "+code);Check(Has(r,code),"specific rejection: "+code);}
    static void VerifyBuild(RaidMetadataProbe.Group g,ArrayOracle oracle,string suffix){Check(g.Status=="candidate"&&g.Configuration!=null,"native DDF configuration available");Check(g.MetadataOnly&&g.RequiresReview&&!g.DataIntegrityEstablished,"metadata remains separate from payload proof");Check(g.Layout==oracle.layout&&g.LogicalBytes==oracle.logical_bytes,"independent decoded layout and size");string output=Path.Combine(work,"assembled-"+suffix);var built=RaidImageBuilder.Build(g.Configuration,output,CancellationToken.None,(d,t)=>{});Check(built.Bytes==oracle.logical_bytes&&Hash(built.ImagePath)==oracle.logical_sha256,"assembled bytes equal independently decoded upstream payload SHA256");using(var input=File.OpenRead(built.ImagePath)){byte[] block=new byte[4096];int expectedBlocks=oracle.level==0?3072:512;bool knownPayload=true;for(int i=1;i<=expectedBlocks;i++){if(input.Read(block,0,block.Length)!=block.Length){knownPayload=false;break;}for(int at=0;at<block.Length;at+=2)if(block[at]!=(byte)i||block[at+1]!=(byte)(i>>8)){knownPayload=false;break;}}Check(knownPayload,"upstream test_ddf.py independent numbered 4KiB payload blocks recovered");}}
    static void NativeDdf(){foreach(var oracle in manifest.arrays){var cases=manifest.cases.Where(f=>f.kind=="native_upstream"&&f.level==oracle.level).ToArray();var paths=cases.Select(PathOf).Reverse().ToArray();var r=Probe(paths);Check(r.Groups.Count==1,"one native DDF virtual disk");var g=r.Groups[0];Check(g.Format=="ddf"&&g.Level==oracle.level.ToString(),"real BE DDF metadata decoded");foreach(var f in cases)Check(g.Configuration.Members[f.role].Path==PathOf(f),"PD GUID/reference resolves member order independent of path/input order");VerifyBuild(g,oracle,"full-"+oracle.level);for(int missing=0;missing<paths.Length;missing++){var reduced=Probe(paths.Where((p,i)=>i!=missing).ToArray());Check(reduced.Groups.Count==1,"missing member still identifies native VD");if(oracle.level==0){NoConfiguration(reduced,"RAID0 missing disk never guessed");continue;}Check(reduced.Groups[0].MissingRoles.Count==1,"exact missing role recorded");VerifyBuild(reduced.Groups[0],oracle,"missing-"+oracle.level+"-"+missing);}}}
    static void LegacyRejection(){foreach(var f in manifest.cases.Where(f=>f.kind=="invalid_legacy_prototype")){var r=Probe(PathOf(f));NoConfiguration(r,"obsolete invented prototype is never accepted: "+f.name);Check(r.Members.All(m=>!m.Supported),"prototype has no supported member");}}
    static void DdfNegatives(){var f=manifest.cases.First(x=>x.kind=="native_upstream"&&x.level==5);Reject(f,"MD_CHECKSUM_INVALID",b=>b[b.Length-40]^=1);Reject(f,"MD_DDF_OPEN_OR_FOREIGN",b=>Header(b,(x,at)=>x[at+49]=1));Reject(f,"MD_DDF_OPEN_OR_FOREIGN",b=>Header(b,(x,at)=>x[at+48]=1));
        Reject(f,"MD_ARRAY_NOT_FULLY_SYNCED",b=>Section(b,208,(x,at,n)=>{x[at+64+32]=16;DdfCrc(x,at,n);}));
        Reject(f,"MD_DDF_MEMBER_BINDING_INVALID",b=>Section(b,224,(x,at,n)=>{Put32(x,at+32,0x12345678);DdfCrc(x,at,n);}));
        Reject(f,"MD_ROLE_TABLE_INCONSISTENT",b=>Section(b,216,(x,at,n)=>{Put32(x,at+516,Be32(x,at+512));DdfCrc(x,at,7*512);}));
        Reject(f,"MD_DATA_OR_SUPER_OFFSET_INVALID",b=>Section(b,216,(x,at,n)=>{Put64(x,at+512+256*4,16384);DdfCrc(x,at,7*512);}));
        Reject(f,"MD_DDF_ARRAY_SIZE_INVALID",b=>Section(b,216,(x,at,n)=>{Put64(x,at+80,1);DdfCrc(x,at,7*512);}));Reject(f,"MD_DATA_OR_SUPER_OFFSET_INVALID",b=>{Header(b,(x,at)=>Put64(x,at+120,0));Put64(b,b.Length-512+120,0);DdfCrc(b,b.Length-512,512);});
        Reject(f,"MD_DDF_LAYOUT_UNSUPPORTED",b=>Section(b,216,(x,at,n)=>{x[at+67]=6;DdfCrc(x,at,7*512);}));
        Reject(f,"MD_PARITY_LAYOUT_UNSUPPORTED",b=>Section(b,216,(x,at,n)=>{x[at+68]=99;DdfCrc(x,at,7*512);}));
        Reject(f,"MD_DDF_COPY_MISMATCH",b=>{int a=b.Length-512,h=(int)Be64(b,a+104)*512;b[h+(int)Be32(b,h+216)*512+20]^=1;});
        Reject(f,"MD_DDF_GENERATION_MISMATCH",b=>{int a=b.Length-512,h=(int)Be64(b,a+104)*512;Put32(b,h+40,Be32(b,h+40)+1);DdfCrc(b,h,512);});
        Reject(f,"MD_DDF_MEMBER_STATE_UNSUPPORTED",b=>Section(b,200,(x,at,n)=>{x[at+64+31]=5;DdfCrc(x,at,n);}));
        string generation=Mutate(f,b=>Section(b,216,(x,at,n)=>{Put32(x,at+36,Be32(x,at+36)+1);DdfCrc(x,at,7*512);}));string other=PathOf(manifest.cases.First(x=>x.kind=="native_upstream"&&x.level==5&&x.name!=f.name));var inconsistent=Probe(generation,other);NoConfiguration(inconsistent,"different VD generations rejected");Check(Has(inconsistent,"MD_EVENT_COUNTER_MISMATCH"),"actual VD sequence counter is compared");
        var token=new CancellationToken(true);bool cancelled=false;try{RaidMetadataProbe.Probe(new[]{PathOf(f)},token);}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"cancellation retained");
    }
    // Spec-shaped IMSM control, not an independent native capture. An MPB is
    // shared by all physical members; it cannot authenticate a current RAW role.
    static string Imsm(bool extended,bool dirty,bool corrupt){byte[] b=new byte[128*1024],mpb=new byte[extended?1024:512];Encoding.ASCII.GetBytes("Intel Raid ISM Cfg Sig. 1.3.00\0\0").CopyTo(mpb,0);Le32(mpb,36,(uint)mpb.Length);Le32(mpb,40,0x12345678);Le32(mpb,44,77);mpb[56]=2;mpb[57]=1;Le32(mpb,64,0x12345678);for(int d=0;d<2;d++){int at=216+d*48;Encoding.ASCII.GetBytes("SERIAL"+d).CopyTo(mpb,at);Le32(mpb,at+16,256);Le32(mpb,at+24,2);}int dev=312,map=424;Encoding.ASCII.GetBytes("SyntheticVolume").CopyTo(mpb,dev);Le32(mpb,dev+16,128);mpb[dev+90]=(byte)(dirty?1:0);Le32(mpb,map+4,128);mpb[map+12]=128;mpb[map+15]=0;mpb[map+16]=2;mpb[map+17]=1;Le32(mpb,map+48,1);Le32(mpb,map+52,0);uint sum=0;for(int i=0;i<mpb.Length;i+=4)if(i!=32)sum=unchecked(sum+BitConverter.ToUInt32(mpb,i));Le32(mpb,32,sum);if(corrupt)mpb[100]^=1;Buffer.BlockCopy(mpb,0,b,b.Length-1024,512);if(extended)Buffer.BlockCopy(mpb,512,b,b.Length-1536,512);string path=Path.Combine(work,"imsm-"+(++number)+".dd");File.WriteAllBytes(path,b);return path;}
    static void ImsmBoundary(){foreach(bool extended in new[]{false,true}){var r=Probe(Imsm(extended,false,false));NoConfiguration(r,"unbound RAW IMSM cannot provide guessed role");Check(Has(r,"MD_IMSM_MEMBER_BINDING_REQUIRED"),"IMSM external device identity requirement explicit");var m=r.Members.First();Check(m.ChecksumValid&&m.Events==77&&m.RaidDisks==2&&m.ChunkBytes==65536,"real MPB field offsets and backwards extension decode");}var dirty=Probe(Imsm(true,true,false));NoConfiguration(dirty,"dirty IMSM remains unsupported");Check(Has(dirty,"MD_ARRAY_NOT_FULLY_SYNCED"),"actual vol.dirty byte checked");var bad=Probe(Imsm(true,false,true));Check(Has(bad,"MD_CHECKSUM_INVALID"),"IMSM checksum strict");}
    public static int Main(string[] args){try{string project=Path.GetFullPath(args.Length>0?args[0]:".");fixtures=Path.GetFullPath(args.Length>1?args[1]:Path.Combine(project,".build","raid-controller-fixtures-current"));work=Path.GetFullPath(args.Length>2?args[2]:Path.Combine(project,".build","raid-controller-tests-"+Guid.NewGuid().ToString("N")));Directory.CreateDirectory(work);manifest=new JavaScriptSerializer().Deserialize<Manifest>(File.ReadAllText(Path.Combine(fixtures,"manifest.json")));foreach(var f in manifest.cases)Check(Hash(PathOf(f))==f.sha256,"pinned source fixture hash");LegacyRejection();NativeDdf();DdfNegatives();ImsmBoundary();Console.WriteLine("PASS RaidControllerRecovery: "+checks+" checks; native upstream DDF0/1/5 payload SHA256 including all single-member degraded cases, metadata CRC/binding/layout/generation negatives; IMSM identity-required and legacy false formats rejected. No native IMSM/Spaces reconstruction claim.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
